77	    pub fn identify(value: &str, strict: bool) -> Case {
78	        let mut chars = value.chars();
79	        let Some(first_char) = chars.next() else {
80	            return Case::Unknown;
81	        };
82	        let mut result = if first_char.is_uppercase() {
83	            Case::NumberableCapital
84	        } else if first_char.is_lowercase() {
85	            Case::Lower
86	        } else if first_char.is_alphanumeric() {
87	            Case::Uni
88	        } else {
89	            return Case::Unknown;
90	        };
91	        let mut previous_char = first_char;
92	        let mut has_consecutive_uppercase = false;
93	        for current_char in chars {
94	            result = match current_char {
95	                '-' => match result {
